        /// <summary>RangeStreamResponse is the response for the RangeStream RPC.</summary>
        [Option(@"(versionpb.etcd_version_msg)", @"3.7")]
        public class RangeStreamResponse {
            /// <summary>
            /// range_response is a partial response for the KV.RangeStream RPC.
            /// The result of proto.Merge() applied on all responses should result in the
            /// same RangeResponse response as to the Range() method.
            ///
            /// Field population across chunks:
            ///   - kvs: each chunk carries a non-empty, disjoint slice of the result (or is
            ///     empty on a single-chunk response when no keys match or count_only is set).
            ///     Concatenating them in order yields the full key set.
            ///   - header, more, count: set only on the final chunk. Non-merge clients
            ///     can rely on io.EOF (end of stream) to detect completion. These
            ///     fields are provided for clients that merge all responses into a
            ///     single RangeResponse.
            /// </summary>
            RangeResponse range_response;
        }

        public struct mvccpb {
            // from etcd/api/mvccpb/kv.proto

            public class KeyValue {
                /// <summary>key is the key in bytes. An empty key is not allowed.</summary>
                Binary[,,] key;

                /// <summary>create_revision is the revision of last creation on this key.</summary>
                [X] long create_revision;

                /// <summary>mod_revision is the revision of last modification on this key.</summary>
                [X] long mod_revision;

                /// <summary>
                /// version is the version of the key. A deletion resets
                /// the version to zero and any modification of the key
                /// increases its version.
                /// </summary>
                [X] long version;

                /// <summary>value is the value held by the key, in bytes.</summary>
                Binary[,,] value;

                /// <summary>
                /// lease is the ID of the lease that attached to key.
                /// When the attached lease expires, the key will be deleted.
                /// If lease is 0, then no lease is attached to the key.
                /// </summary>
                [X] long lease;
            }

            public class Event {
                public enum EventType {
                    PUT = 0,
                    DELETE = 1,
                }

                /// <summary>
                /// type is the kind of event. If type is a PUT, it indicates
                /// new data has been stored to the key. If type is a DELETE,
                /// it indicates the key was deleted.
                /// </summary>
                EventType Type;

                /// <summary>
                /// kv holds the KeyValue for the event.
                /// A PUT event contains current kv pair.
                /// A PUT event with kv.Version=1 indicates the creation of a key.
                /// A DELETE/EXPIRE event contains the deleted key with
                /// its modification revision set to the revision of deletion.
                /// </summary>
                KeyValue kv;

                /// <summary>prev_kv holds the key-value pair before the event happens.</summary>
                KeyValue prev_kv;
            }
        }

        public struct authpb {
            // from etcd/api/authpb/auth.proto

            public class UserAddOptions {
                bool no_password;
            }

            /// <summary>Permission is a single entity</summary>
            public class Permission {
                public enum Type {
                    READ = 0,
                    WRITE = 1,
                    READWRITE = 2,
                }

                Type permType;
                Binary[,,] key;
                Binary[,,] range_end;
            }
        }

        // ═════════════════════════ topology ═════════════════════════

        /// <summary>Answers the calls: implements the services.</summary>
        ///<see cref = 'InTS'/>   implementation in TypeScript
        ///<see cref = 'InCS'/>   implementation in C#
        ///<see cref = 'InJAVA'/> implementation in JAVA
        ///<see cref = 'InCPP'/>  implementation in C++
        ///<see cref = 'InRS'/>   implementation in RUST
        ///<see cref = 'InGO'/>   implementation in GO
        struct Server : Host { }

        /// <summary>Makes the calls.</summary>
        ///<see cref = 'InTS'/>   implementation in TypeScript
        ///<see cref = 'InCS'/>   implementation in C#
        ///<see cref = 'InJAVA'/> implementation in JAVA
        ///<see cref = 'InCPP'/>  implementation in C++
        ///<see cref = 'InRS'/>   implementation in RUST
        ///<see cref = 'InGO'/>   implementation in GO
        struct Client : Host { }

        interface ClientServerConnection : Connects<Client, Server> {
            public interface KV {
                /// <summary>Range gets the keys in the range from the key-value store.</summary>
